async Task RunSafeAsync(Func<Task> work)
{
    try { await work(); }                                   // ждём внутри обёртки
    catch (Exception e) { log.LogError(e, "фоновая задача упала"); }
}

_ = RunSafeAsync(() => SendEmailAsync(user));   // не ждём нарочно, ошибка попадёт в лог
